import java.util.ArrayList;

public class Pila {
    private ArrayList<Integer> dati = new ArrayList<>();

    public void push(int x) {
        dati.add(x);
    }

    public int pop() {
        return dati.remove(dati.size() - 1);
    }
}

public class Main {
    public static void main(String[] args) {
        Pila p = new Pila();
        p.push(5);
        p.push(8);
        System.out.println(p.pop());
        System.out.println(p.pop());
    }
}
